// Server-only trivia key. Hosting does not serve functions/.
// Git history still has the previous key, so these questions stay guessable until the bank is rotated.
var TRIVIA_BANK=[{"q":"What date is inscribed in the Bitcoin genesis block?","options":["January 9, 2009","October 31, 2008","January 3, 2009","November 1, 2008"],"answer":2,"explanation":"The genesis block (Block 0) was mined on January 3, 2009, and contains a Times headline from that date."},{"q":"What newspaper headline did Satoshi embed in the genesis block?","options":["Banks receive government lifeline","Chancellor on brink of second bailout for banks","Global financial crisis deepens","Federal Reserve cuts rates to zero"],"answer":1,"explanation":"Satoshi embedded 'The Times 03/Jan/2009 Chancellor on brink of second bailout for banks' as a timestamp proof and political statement."},{"q":"When was the Bitcoin whitepaper published?","options":["August 18, 2008","November 1, 2008","October 31, 2008","January 3, 2009"],"answer":2,"explanation":"Satoshi Nakamoto published 'Bitcoin: A Peer-to-Peer Electronic Cash System' on October 31, 2008, via the cryptography mailing list."},{"q":"Who received the first ever Bitcoin transaction from Satoshi Nakamoto?","options":["Wei Dai","Nick Szabo","Adam Back","Hal Finney"],"answer":3,"explanation":"Hal Finney received 10 BTC from Satoshi in block 170 on January 12, 2009, making it the first known person-to-person Bitcoin transaction."},{"q":"How many bitcoins were paid for two pizzas on Bitcoin Pizza Day (May 22, 2010)?","options":["10,000 BTC","1,000 BTC","50,000 BTC","5,000 BTC"],"answer":0,"explanation":"Laszlo Hanyecz paid 10,000 BTC for two Papa John's pizzas, marking the first known real-world Bitcoin transaction."},{"q":"Which Bitcoin exchange suffered a major hack in 2014, losing approximately 850,000 BTC?","options":["BTC-e","Bitstamp","Bitfinex","Mt. Gox"],"answer":3,"explanation":"Mt. Gox, once handling over 70% of all Bitcoin transactions, filed for bankruptcy in February 2014 after losing roughly 850,000 BTC."},{"q":"What was the name of the online marketplace that popularized Bitcoin for illicit transactions, shut down by the FBI in 2013?","options":["Silk Road","Agora","AlphaBay","Evolution"],"answer":0,"explanation":"Silk Road, operated by Ross Ulbricht (Dread Pirate Roberts), was seized by the FBI in October 2013 and demonstrated Bitcoin's use as censorship-resistant money."},{"q":"In what year did the Bitcoin block reward first halve from 50 BTC to 25 BTC?","options":["2013","2012","2011","2014"],"answer":1,"explanation":"The first Bitcoin halving occurred on November 28, 2012, at block 210,000, reducing the block reward from 50 to 25 BTC."},{"q":"Which hard fork of Bitcoin occurred on August 1, 2017, creating a new cryptocurrency with larger blocks?","options":["Bitcoin SV","Bitcoin Gold","Bitcoin Cash","Bitcoin Diamond"],"answer":2,"explanation":"Bitcoin Cash (BCH) forked from Bitcoin on August 1, 2017, increasing the block size limit from 1 MB to 8 MB."},{"q":"What was Satoshi Nakamoto's last known public communication?","options":["A post on the BitcoinTalk forum in December 2010","A message on the cryptography mailing list in January 2011","A commit to the Bitcoin codebase in March 2011","An email to Gavin Andresen in April 2011"],"answer":3,"explanation":"Satoshi's last known communication was an email to developer Gavin Andresen in April 2011, after which Satoshi went silent."},{"q":"What event is known as the 'Blocksize War'?","options":["The 2015-2017 debate over increasing Bitcoin's block size","The 2013 fork caused by a software bug","The 2018 hash war between Bitcoin ABC and Bitcoin SV","The competition between Bitcoin and Bitcoin Cash miners"],"answer":0,"explanation":"The Blocksize War was a multi-year debate (2015-2017) over whether to increase Bitcoin's block size, ultimately resolved with SegWit activation and the Bitcoin Cash fork."},{"q":"Which upgrade activated on Bitcoin in August 2017, fixing transaction malleability?","options":["CheckSequenceVerify","Segregated Witness (SegWit)","Taproot","Pay-to-Script-Hash"],"answer":1,"explanation":"SegWit separated signature data from transaction data, fixing the transaction malleability bug and enabling second-layer solutions like Lightning Network."},{"q":"What is the name of the domain where the Bitcoin whitepaper was originally hosted?","options":["sourceforge.net","bitcoin.com","bitcointalk.org","bitcoin.org"],"answer":3,"explanation":"Satoshi registered bitcoin.org in August 2008 and published the whitepaper there in October 2008."},{"q":"Which early Bitcoin developer was given commit access to the Bitcoin repository by Satoshi before disappearing?","options":["Jeff Garzik","Gregory Maxwell","Gavin Andresen","Pieter Wuille"],"answer":2,"explanation":"Satoshi handed lead development to Gavin Andresen in 2011 before going silent, making Gavin the de facto lead maintainer."},{"q":"When did the Taproot upgrade activate on Bitcoin?","options":["June 2022","November 2021","August 2017","November 2020"],"answer":1,"explanation":"Taproot activated at block 709,632 on November 14, 2021, bringing Schnorr signatures and improved smart contract capabilities."},{"q":"What hashing algorithm does Bitcoin use for mining (proof of work)?","options":["Ethash","SHA-256","Blake2b","Scrypt"],"answer":1,"explanation":"Bitcoin uses the SHA-256 (Secure Hash Algorithm 256-bit) hashing function, which miners must repeatedly compute to find valid blocks."},{"q":"How often does Bitcoin's mining difficulty adjust?","options":["Every 2,016 blocks (~2 weeks)","Every 1,000 blocks (~1 week)","Every 4,032 blocks (~4 weeks)","Every block"],"answer":0,"explanation":"Bitcoin adjusts difficulty every 2,016 blocks (approximately every two weeks) to maintain the target of one block every ~10 minutes."},{"q":"What is the maximum size of a legacy Bitcoin block?","options":["2 MB","1 MB","8 MB","4 MB"],"answer":1,"explanation":"Legacy Bitcoin blocks are limited to 1 MB. With SegWit, the effective limit is measured in weight units, allowing up to about 4 MB of total block weight."},{"q":"What does UTXO stand for in Bitcoin?","options":["Unspent Transaction Output","Universal Token Transfer Object","Unsigned Transaction Operation","Unified Transaction Exchange Order"],"answer":0,"explanation":"UTXOs are Unspent Transaction Outputs — the fundamental building blocks of Bitcoin's accounting model, representing spendable coins."},{"q":"What is the target average time between Bitcoin blocks?","options":["10 minutes","15 minutes","5 minutes","1 minute"],"answer":0,"explanation":"Bitcoin's difficulty adjustment algorithm targets an average block time of 10 minutes, though individual blocks can vary significantly."},{"q":"What is a Bitcoin mempool?","options":["A pool of mining hardware","A type of memory storage for nodes","A waiting area for unconfirmed transactions","A collection of expired blocks"],"answer":2,"explanation":"The mempool (memory pool) is where valid but unconfirmed transactions wait before being included in a block by miners."},{"q":"What type of cryptography does Bitcoin use for digital signatures?","options":["Elliptic Curve Digital Signature Algorithm (ECDSA)","AES-256","RSA","Diffie-Hellman"],"answer":0,"explanation":"Bitcoin originally uses ECDSA with the secp256k1 curve for signing transactions. Taproot added support for Schnorr signatures."},{"q":"What is a Merkle tree used for in Bitcoin?","options":["Efficiently summarizing and verifying all transactions in a block","Encrypting private keys","Routing payments across the network","Generating new Bitcoin addresses"],"answer":0,"explanation":"A Merkle tree hashes all transactions in a block into a single root hash, allowing efficient verification that a specific transaction is included in a block."},{"q":"How many confirmations are generally considered secure for a large Bitcoin transaction?","options":["6 confirmations","10 confirmations","1 confirmation","3 confirmations"],"answer":0,"explanation":"Six confirmations (~60 minutes) is the traditional threshold for considering a transaction practically irreversible, though smaller transactions may require fewer."},{"q":"What is the Bitcoin scripting language called?","options":["Solidity","Clarity","Move","Script"],"answer":3,"explanation":"Bitcoin uses a stack-based scripting language simply called 'Script.' It is intentionally not Turing-complete to reduce attack surfaces."},{"q":"What does SegWit measure block capacity in?","options":["Megabytes","Weight units (WU)","Transactions per second","Virtual bytes"],"answer":1,"explanation":"SegWit introduced weight units, with a maximum block weight of 4,000,000 WU. Witness data is discounted, effectively allowing larger blocks."},{"q":"What is a nonce in Bitcoin mining?","options":["The network fee attached to a transaction","A one-time cryptographic key for transactions","A unique identifier for each Bitcoin address","A number miners change to produce a valid block hash"],"answer":3,"explanation":"The nonce is a 32-bit field in the block header that miners increment to find a hash below the target difficulty."},{"q":"What is an SPV (Simplified Payment Verification) node?","options":["A node that processes only SegWit transactions","A lightweight node that verifies transactions using block headers without downloading the full blockchain","A mining node with simplified hardware","A node that only stores the most recent 100 blocks"],"answer":1,"explanation":"SPV nodes download only block headers and use Merkle proofs to verify transactions, as described in Satoshi's whitepaper, enabling lightweight wallets."},{"q":"What is the coinbase transaction?","options":["The very first Bitcoin transaction ever made","A transaction that destroys bitcoins permanently","The first transaction in every block that creates new bitcoins as a mining reward","A transaction on the Coinbase exchange"],"answer":2,"explanation":"The coinbase transaction is the first transaction in each block, created by the miner, which generates new BTC (the block subsidy) plus collects transaction fees."},{"q":"What is the maximum number of weight units allowed in a Bitcoin block?","options":["4,000,000 WU","2,000,000 WU","8,000,000 WU","1,000,000 WU"],"answer":0,"explanation":"Post-SegWit, Bitcoin blocks are limited to 4 million weight units. Non-witness data counts as 4 WU per byte, while witness data counts as 1 WU per byte."},{"q":"What is the maximum supply of Bitcoin?","options":["21 million","18 million","42 million","100 million"],"answer":0,"explanation":"Bitcoin's protocol enforces a hard cap of 21 million coins, making it the first provably scarce digital asset."},{"q":"How often does the Bitcoin block reward halve?","options":["Every year","Every 500,000 blocks (~10 years)","Every 210,000 blocks (~4 years)","Every 100,000 blocks (~2 years)"],"answer":2,"explanation":"The block reward halves every 210,000 blocks, approximately every four years, reducing the rate of new Bitcoin creation."},{"q":"What was the block reward after the 2024 halving?","options":["6.25 BTC","12.5 BTC","1.5625 BTC","3.125 BTC"],"answer":3,"explanation":"The April 2024 halving (the fourth) reduced the block reward from 6.25 BTC to 3.125 BTC per block."},{"q":"Approximately what percentage of all Bitcoin has already been mined as of 2024?","options":["Over 93%","About 88%","About 80%","About 75%"],"answer":0,"explanation":"By 2024, over 19.5 million of the 21 million total bitcoins have been mined, representing more than 93% of the total supply."},{"q":"What is the smallest unit of Bitcoin called?","options":["Finney","Satoshi","Wei","Gwei"],"answer":1,"explanation":"A satoshi (sat) is 0.00000001 BTC — one hundred millionth of a bitcoin, named after Bitcoin's creator."},{"q":"What economic concept does the stock-to-flow model measure?","options":["The ratio of existing supply to annual production","The total market capitalization divided by trading volume","The velocity of money in the Bitcoin network","The ratio of buy orders to sell orders"],"answer":0,"explanation":"Stock-to-flow divides existing supply (stock) by annual new production (flow). Bitcoin's ratio increases with each halving, similar to gold and silver."},{"q":"In approximately what year will the last Bitcoin be mined?","options":["2140","2100","2200","2050"],"answer":0,"explanation":"Due to the halving schedule, the block reward will become negligibly small, with the last satoshi expected to be mined around the year 2140."},{"q":"What happens to Bitcoin miners' revenue when the block subsidy eventually reaches zero?","options":["Mining will stop and the network will shut down","They will rely entirely on transaction fees","Miners will be paid by the Bitcoin Foundation","A new subsidy will be voted on by miners"],"answer":1,"explanation":"Once all 21 million BTC are mined, miners will be incentivized solely by transaction fees included in each block."},{"q":"What is the term for the reduction in Bitcoin's annual inflation rate after each halving?","options":["Deflationary","Reflationary","Hyperinflationary","Disinflationary"],"answer":3,"explanation":"Bitcoin is disinflationary — new coins are still created, but at a decreasing rate. After all coins are mined, lost coins make the effective supply deflationary."},{"q":"What does 'difficulty epoch' refer to in Bitcoin?","options":["A period when no blocks are found for over an hour","A period of extreme price volatility","The time between two halvings","A period of 2,016 blocks between difficulty adjustments"],"answer":3,"explanation":"A difficulty epoch is the 2,016-block window (~2 weeks) after which Bitcoin's proof-of-work difficulty is recalculated."},{"q":"What is the 'block subsidy' in Bitcoin?","options":["The newly created BTC awarded to the miner who finds a block","A fee paid by users to prioritize transactions","The cost of electricity required to mine a block","A fund maintained by Bitcoin Core developers"],"answer":0,"explanation":"The block subsidy is the newly minted BTC in each block's coinbase transaction. It started at 50 BTC and halves every 210,000 blocks."},{"q":"What is a 'fee market' in Bitcoin?","options":["A marketplace for buying and selling Bitcoin mining contracts","A derivatives market for hedging transaction costs","An exchange where miners sell their block rewards","Competition among users to have their transactions included by paying higher fees"],"answer":3,"explanation":"When block space is scarce, users compete by offering higher fees to incentivize miners to include their transactions, creating a fee market."},{"q":"How many satoshis are in one Bitcoin?","options":["100,000,000","1,000,000,000","1,000,000","10,000,000"],"answer":0,"explanation":"One Bitcoin equals 100 million satoshis. This high divisibility allows Bitcoin to be used for microtransactions."},{"q":"What is the term for Bitcoin that has been sent to an unspendable address, permanently removing it from circulation?","options":["Vault locked","Burned","Permanently staked","Protocol bonded"],"answer":1,"explanation":"Burning Bitcoin means sending it to a provably unspendable address (like an address with no known private key), permanently reducing the circulating supply."},{"q":"Where does the term 'HODL' originate?","options":["An acronym coined by Satoshi Nakamoto in the whitepaper","A misspelled forum post on BitcoinTalk in 2013","A meme that first appeared on Reddit in early 2015","A Wall Street trading strategy adapted for crypto"],"answer":1,"explanation":"HODL originated from a typo in a 2013 BitcoinTalk forum post titled 'I AM HODLING' by user GameKyuubi during a price crash."},{"q":"What does the phrase 'Not your keys, not your coins' mean?","options":["Bitcoin can only be sent using hardware wallets","You need physical keys to access Bitcoin ATMs","Exchanges always guarantee the safety of your funds","If you don't control your private keys, you don't truly own your Bitcoin"],"answer":3,"explanation":"This phrase warns that Bitcoin held on exchanges or custodial services can be lost if the custodian is hacked or goes bankrupt, as happened with Mt. Gox."},{"q":"What does it mean when someone says they have 'laser eyes' on social media?","options":["They are bullish on Bitcoin and showing support for a BTC price target","They run a large-scale Bitcoin mining operation using proof-of-work hardware","They are a Bitcoin Core developer who has contributed code to the protocol","They have completed an on-chain identity verification through a smart contract"],"answer":0,"explanation":"Laser eyes became a Bitcoin meme in 2021, with supporters adding laser eyes to profile photos to signal bullishness and support for Bitcoin reaching $100K."},{"q":"What is a 'Bitcoin Maximalist'?","options":["A miner running the most powerful hardware available for proof of work","A person who owns the maximum possible amount of Bitcoin in a single wallet","Someone who believes Bitcoin is the only cryptocurrency that matters","A developer who has contributed the most lines of code to Bitcoin Core software"],"answer":2,"explanation":"Bitcoin Maximalists (or 'maxis') believe Bitcoin is the only legitimate cryptocurrency and that altcoins are unnecessary or harmful."},{"q":"What does 'number go up' (NGU) technology refer to in Bitcoin culture?","options":["A proposed technical improvement to increase Bitcoin transaction throughput speed","The humorous observation that Bitcoin's price trends upward over long periods","An algorithm designed to automatically increase the mining difficulty over time","A data compression method for reducing the size of the blockchain on full nodes"],"answer":1,"explanation":"'NGU technology' is a tongue-in-cheek meme celebrating Bitcoin's long-term price appreciation as if it were a feature of the protocol."},{"q":"What does 'stacking sats' mean?","options":["Building a physical stack of ASIC mining rigs for profit","Organizing satellite nodes for the Bitcoin network","Compiling and organizing Bitcoin transaction data locally","Accumulating small amounts of Bitcoin over time"],"answer":3,"explanation":"Stacking sats means regularly buying small amounts of Bitcoin (measured in satoshis), often through dollar-cost averaging."},{"q":"Who is often credited with conceptualizing digital cash and 'bit gold' before Bitcoin?","options":["Satoshi Nakamoto","Hal Finney Jr.","Nick Szabo","David Chaum"],"answer":2,"explanation":"Nick Szabo proposed 'Bit Gold' in 1998, a decentralized digital currency concept that shares many similarities with Bitcoin."},{"q":"What is the 'Citadel' meme in Bitcoin culture?","options":["A well-known cooperative Bitcoin mining pool that early adopters frequently joined","A future scenario where early Bitcoin adopters live in fortified communities","The rumored physical headquarters of the anonymous Bitcoin Foundation leadership","A type of ultra-secure cold storage Bitcoin vault system with multisig protection"],"answer":1,"explanation":"The Citadel meme imagines a hyperbitcoinized future where early adopters live in citadels, originating from a famous Reddit post claiming to be from the year 2025."},{"q":"What does 'FUD' stand for in crypto communities?","options":["Future Unlimited Digital Dividends","Fully Utilized Decentralization","Fear, Uncertainty, and Doubt","Fundamentally Unverified Data"],"answer":2,"explanation":"FUD (Fear, Uncertainty, and Doubt) refers to negative information or sentiment spread to discourage people from buying or holding Bitcoin."},{"q":"What is a 'whole coiner' in Bitcoin terminology?","options":["A miner who has mined an entire block solo","Someone who has read the entire Bitcoin whitepaper","Someone who owns at least 1 full Bitcoin","A full node operator running the Bitcoin Core software"],"answer":2,"explanation":"A 'whole coiner' is someone who owns at least one complete Bitcoin. With Bitcoin's rising price, this has become an aspirational milestone."},{"q":"Who wrote 'The Bitcoin Standard,' an influential book on Bitcoin's monetary properties?","options":["Michael J. Saylor","Andreas Antonopoulos","Jameson Lopp, Jr.","Saifedean Ammous"],"answer":3,"explanation":"Saifedean Ammous published 'The Bitcoin Standard' in 2018, arguing for Bitcoin as sound money through the lens of Austrian economics."},{"q":"What does 'HFSP' stand for in Bitcoin Twitter culture?","options":["Have Fun Staying Poor","Hyper-Funded Protocol","Halving Follows Supply Pattern","Hash Function Security Protocol for Blockchain Networks"],"answer":0,"explanation":"'Have Fun Staying Poor' is a dismissive phrase used by Bitcoin enthusiasts toward skeptics, popularized on Twitter/X by Bitcoin maximalists."},{"q":"What is the significance of the Bitcoin 'B' symbol (₿)?","options":["It represents the binary nature of digital currency","It was created by the Bitcoin Foundation in 2014","It was designed by Satoshi Nakamoto in 2008","It was adopted as the official Unicode symbol for Bitcoin in 2017"],"answer":3,"explanation":"The ₿ symbol was added to the Unicode Standard in June 2017 (Unicode 10.0), giving Bitcoin an official currency symbol alongside $, €, and ¥."},{"q":"What annual event celebrates the first real-world Bitcoin purchase?","options":["Bitcoin Freedom Celebration Day (August 1)","Genesis Day","Bitcoin Pizza Day (May 22)","Bitcoin Halving Day"],"answer":2,"explanation":"Bitcoin Pizza Day on May 22 commemorates Laszlo Hanyecz's 2010 purchase of two pizzas for 10,000 BTC, the first known commercial Bitcoin transaction."},{"q":"What is the Lightning Network?","options":["A mining pool that processes transactions faster","A faster version of the Bitcoin blockchain","A Layer 2 payment protocol built on top of Bitcoin for fast, cheap transactions","An alternative cryptocurrency inspired by Bitcoin"],"answer":2,"explanation":"The Lightning Network is a Layer 2 protocol that enables near-instant, low-fee Bitcoin payments through a network of payment channels."},{"q":"What must two parties open to transact on the Lightning Network?","options":["A dedicated smart contract address","A shared mining operation pool","An independent Bitcoin sidechain connection","A payment channel"],"answer":3,"explanation":"Lightning Network participants open payment channels by locking Bitcoin in a 2-of-2 multisig on-chain transaction, then transact off-chain within that channel."},{"q":"Who authored the original Lightning Network whitepaper?","options":["Nakamoto and Finney","Joseph Poon and Thaddeus Dryja","Gregory Maxwell and Adam Back together","Elizabeth Stark with Olaoluwa Osuntokun"],"answer":1,"explanation":"Joseph Poon and Thaddeus Dryja published 'The Bitcoin Lightning Network' paper in 2015, describing the off-chain payment channel network."},{"q":"What Bitcoin feature was essential for the Lightning Network to work safely?","options":["The OP_RETURN data embedding function","Bitcoin's Replace-by-Fee transaction mechanism","Segregated Witness (SegWit)","The Taproot soft fork upgrade"],"answer":2,"explanation":"SegWit fixed the transaction malleability problem, which was essential because Lightning relies on pre-signed transactions referencing specific transaction IDs."},{"q":"What happens when a Lightning Network channel is closed?","options":["Every individual transaction from the channel is permanently recorded on-chain in full detail","The final balance is settled on the Bitcoin blockchain","It reopens","All locked funds are completely destroyed and then freshly re-minted as new coins"],"answer":1,"explanation":"When a Lightning channel closes, a final settlement transaction is broadcast to the Bitcoin blockchain reflecting the latest balance between the two parties."},{"q":"What is 'routing' in the Lightning Network?","options":["Directing mining power to specific blocks","Finding a path of connected channels to send a payment to someone you don't have a direct channel with","Selecting the fastest blockchain for settlement","Choosing which Bitcoin node to connect to"],"answer":1,"explanation":"Lightning routing finds multi-hop paths through the network, allowing payments between parties who don't share a direct channel."},{"q":"What is an 'invoice' in the Lightning Network?","options":["A record of all channel openings on the network","A payment request containing amount, destination, and expiry encoded in a string","A tax document for Lightning transactions","A receipt generated after an on-chain transaction"],"answer":1,"explanation":"A Lightning invoice (BOLT 11) is a payment request that encodes the payment hash, amount, destination node, and expiry time."},{"q":"What is 'channel capacity' on the Lightning Network?","options":["The total bandwidth and speed capacity of a Lightning node's dedicated internet connection","The total amount of Bitcoin locked in a payment channel","How many simultaneous channels one node opens","Maximum transactions processed"],"answer":1,"explanation":"Channel capacity is the total Bitcoin locked in the channel's funding transaction. Payments within the channel cannot exceed this amount."},{"q":"What is a 'watchtower' in the context of Lightning Network?","options":["Enhanced full nodes","A node that validates Lightning invoices","A service that monitors channels and broadcasts penalty transactions if a counterparty cheats","A mandatory government-run surveillance tool used for actively monitoring and tracking all Bitcoin transactions on the public network"],"answer":2,"explanation":"Watchtowers protect Lightning users by monitoring the blockchain for fraudulent channel closes and broadcasting penalty transactions on their behalf."},{"q":"What is the unit typically used for Lightning Network payments?","options":["Whole Bitcoin units only","Special Lightning network credits","Satoshis (sats)","Millisatoshis or msats"],"answer":2,"explanation":"While the Lightning Network internally tracks millisatoshis (1/1000th of a sat), payments are typically denominated in satoshis."},{"q":"Which popular Lightning Network implementation is developed by Lightning Labs?","options":["Core Lightning (CLN)","The Eclair implementation","LND","Electrum Lightning Extension"],"answer":2,"explanation":"LND (Lightning Network Daemon) is developed by Lightning Labs and is one of the most widely used Lightning implementations."},{"q":"What is a 'submarine swap' in Bitcoin's Lightning ecosystem?","options":["A privacy method for concealing Lightning payment amounts from observers","A technique for merging channels together","Cross-blockchain token swapping","An atomic swap between on-chain Bitcoin and Lightning Bitcoin"],"answer":3,"explanation":"Submarine swaps allow trustless exchanges between on-chain and off-chain (Lightning) Bitcoin, useful for channel rebalancing and liquidity management."},{"q":"What is 'inbound liquidity' on the Lightning Network?","options":["The rate at which new channels are opened to your node","The speed at which your node processes incoming payments","The amount of Bitcoin on the remote side of your channels that others can send to you","The total Bitcoin you have locked in all your channels"],"answer":2,"explanation":"Inbound liquidity is the capacity others have to send you payments. New channels start with all funds on your side (outbound only), making inbound liquidity a common challenge."},{"q":"What is BOLT in the context of Lightning Network?","options":["Binary Optimized Lightning Transfer protocol specifications","A popular and widely-used mobile wallet application designed for everyday Lightning payments","Basis of Lightning Technology — the specification documents for Lightning","Off-chain Ledger Technology"],"answer":2,"explanation":"BOLT (Basis of Lightning Technology) is the set of specification documents that define how Lightning Network implementations should operate and interoperate."},{"q":"What is a 'seed phrase' (mnemonic phrase) in Bitcoin?","options":["A secret code shared between miners","A set of 12 or 24 words that can recover a Bitcoin wallet","A password used to encrypt the blockchain","The genesis block's encoded message"],"answer":1,"explanation":"A seed phrase (BIP-39) is a human-readable representation of a wallet's master private key. Anyone with the phrase can reconstruct and access the wallet."},{"q":"What is 'cold storage' in Bitcoin?","options":["Keeping private keys on a device that is never connected to the internet","Freezing a Bitcoin account on an exchange","Storing Bitcoin in a refrigerated data center","A method of compressing blockchain data for archival"],"answer":0,"explanation":"Cold storage means storing private keys offline (hardware wallets, paper wallets, air-gapped computers), protecting them from online hacks."},{"q":"What is multisignature (multisig) in Bitcoin?","options":["A multi-cryptocurrency wallet supporting various coins","Miner-signed transactions","The requirement for multiple blockchain confirmations before considering a transaction valid","A setup requiring multiple private keys to authorize a transaction"],"answer":3,"explanation":"Multisig requires M-of-N private keys to spend (e.g., 2-of-3), adding security by ensuring no single key compromise can move funds."},{"q":"What is CoinJoin?","options":["A privacy technique that combines multiple users' transactions into one","Wallet merging protocol","Consolidating multiple UTXOs into a single output","A standard protocol used for joining and coordinating mining pools together"],"answer":0,"explanation":"CoinJoin mixes multiple users' inputs and outputs in a single transaction, making it harder to trace which input corresponds to which output."},{"q":"What is a '51% attack' in Bitcoin?","options":["When 51% of all Bitcoin is held by one address","When 51% of nodes reject a software update","When a wallet loses more than 51% of its funds","When a single entity controls more than half the network's mining power, enabling double-spends"],"answer":3,"explanation":"A 51% attack allows an entity controlling majority hash power to reorganize blocks and double-spend, though it's prohibitively expensive on Bitcoin's network."},{"q":"What is a hardware wallet?","options":["A specialized USB drive that contains a fully complete and synchronized copy of the entire Bitcoin blockchain","Specialized mining rig hardware","A physical device that stores private keys offline and signs transactions securely","A dedicated full-node computer"],"answer":2,"explanation":"Hardware wallets (like Ledger, Trezor, Coldcard) store private keys in secure hardware, signing transactions without exposing keys to potentially compromised computers."},{"q":"What is a 'dusting attack' in Bitcoin?","options":["Mining intentionally empty blocks to slow network","Network spam flooding","Simultaneously stealing very small fractional amounts from thousands of different wallets at once","Sending tiny amounts of BTC to many addresses to track spending patterns"],"answer":3,"explanation":"In a dusting attack, tiny amounts of BTC (dust) are sent to many addresses. If recipients spend the dust, analysts can link addresses and deanonymize users."},{"q":"What does BIP-39 define?","options":["The mnemonic code standard for generating deterministic wallets","Bitcoin's mining difficulty adjustment algorithm","The Lightning Network's standardized routing and payment channel protocol specification document","SegWit format"],"answer":0,"explanation":"BIP-39 defines the standard for mnemonic seed phrases (12/24 words from a 2048-word list) used to generate deterministic wallet keys."},{"q":"What is a 'passphrase' (25th word) in the context of seed phrases?","options":["The last word in a 24-word seed phrase","An optional extra word added to a seed phrase that creates a completely different wallet","The password to unlock a hardware wallet","A recovery phrase used if you forget your PIN"],"answer":1,"explanation":"An optional passphrase (sometimes called the 25th word) extends the seed phrase. Different passphrases derive completely different wallets, enabling plausible deniability."},{"q":"What is the purpose of a Bitcoin 'watch-only' wallet?","options":["Real-time price observation","To monitor a wallet's balance and transactions without the ability to spend","A tool for monitoring the full mempool for any specific pending transaction activity","Watching other users' blockchain activity"],"answer":1,"explanation":"Watch-only wallets import only public keys (xpub), allowing balance monitoring without the private keys needed to spend — useful for tracking cold storage."},{"q":"What is a 'time-lock' in Bitcoin transactions?","options":["A lock on an exchange account after failed login attempts","A scheduled automatic Bitcoin purchase","A limit on how long a transaction stays in the mempool","A condition that prevents a transaction from being spent until a specified block height or time"],"answer":3,"explanation":"Time-locks (nLockTime, OP_CLTV, OP_CSV) restrict when a transaction output can be spent, enabling features like payment channels, inheritance planning, and vaults."},{"q":"Why is address reuse considered bad practice in Bitcoin?","options":["Address expiration","It significantly and noticeably increases the transaction fees that are charged by the entire Bitcoin network","It reduces privacy by linking multiple transactions to the same address","It directly violates Bitcoin protocol rules"],"answer":2,"explanation":"Reusing addresses makes it easy for blockchain analysts to link your transactions and build a profile of your spending habits, reducing financial privacy."},{"q":"What is a 'brain wallet' and why is it dangerous?","options":["A wallet generated from a memorized passphrase, vulnerable to brute-force attacks","A wallet securely stored and distributed across multiple cloud-based neural network infrastructure systems worldwide","Quantum-resistant wallet design","AI-powered trading wallet"],"answer":0,"explanation":"Brain wallets derive private keys from memorized phrases, but humans choose predictable phrases. Attackers pre-compute keys from common phrases and steal funds."},{"q":"What does 'coin control' refer to in Bitcoin wallets?","options":["Controlling the rate at which new coins are mined","Setting limits on how much Bitcoin can be sent per day","A government regulatory framework for Bitcoin","Manually selecting which UTXOs to use when constructing a transaction"],"answer":3,"explanation":"Coin control lets users choose specific UTXOs for a transaction, improving privacy by avoiding linking unrelated UTXOs and managing change outputs."},{"q":"Which country became the first to adopt Bitcoin as legal tender in 2021?","options":["The nation of Panama","El Salvador","Central American Honduras","The Republic of Paraguay"],"answer":1,"explanation":"El Salvador, under President Nayib Bukele, passed the Bitcoin Law in June 2021, making Bitcoin legal tender alongside the US dollar."},{"q":"What is El Salvador's government-backed Bitcoin wallet called?","options":["Strike Global","BlueWallet Lightning","Chivo","Muun Wallet"],"answer":2,"explanation":"Chivo Wallet was launched by the Salvadoran government in September 2021 to facilitate Bitcoin and dollar transactions for citizens."},{"q":"In January 2024, the SEC approved which type of Bitcoin investment product?","options":["Government-backed Bitcoin savings bonds","Standardized Bitcoin options trading contracts","Bitcoin futures exchange-traded funds","Spot Bitcoin ETFs"],"answer":3,"explanation":"The SEC approved 11 spot Bitcoin ETFs on January 10, 2024, allowing traditional investors to gain exposure to Bitcoin through regulated brokerage accounts."},{"q":"Which company, led by Michael Saylor, became famous for its massive Bitcoin treasury holdings?","options":["MicroStrategy","Block (formerly Square)","Tesla Motors Inc","Galaxy Digital Holdings"],"answer":0,"explanation":"MicroStrategy (now Strategy), under CEO Michael Saylor, began buying Bitcoin in August 2020 and accumulated hundreds of thousands of BTC as a treasury reserve."},{"q":"Which major electric vehicle company announced a $1.5 billion Bitcoin purchase in February 2021?","options":["Lucid Motors Group","Rivian Automotive","NIO Electric Vehicles","Tesla"],"answer":3,"explanation":"Tesla disclosed a $1.5 billion Bitcoin purchase in an SEC filing in February 2021, briefly accepting BTC for vehicle purchases."},{"q":"What is the primary environmental criticism of Bitcoin mining?","options":["E-waste","High energy consumption from proof-of-work mining","Excessive industrial water usage needed for cooling large mining facility operations","Deforestation to build mining farms"],"answer":1,"explanation":"Critics argue Bitcoin's proof-of-work consensus requires significant electricity. Proponents counter that a growing portion comes from renewable sources and stranded energy."},{"q":"What is the Bitcoin Mining Council?","options":["Government mining regulator","A voluntary group of mining companies that promotes transparency about energy usage","An official centralized government organization that directly allocates and controls Bitcoin mining difficulty adjustment settings","A consortium controlling Bitcoin hash rate"],"answer":1,"explanation":"The Bitcoin Mining Council, formed in 2021, is a voluntary forum of mining companies that collects and shares data on Bitcoin mining's energy mix and sustainability."},{"q":"Which African country's central bank issued warnings about Bitcoin while the country saw rapid grassroots adoption?","options":["West African Ghana","Nigeria","East African Kenya","Republic of South Africa"],"answer":1,"explanation":"Nigeria's central bank restricted bank-to-crypto transactions in 2021, yet Nigeria remained one of the top countries for Bitcoin peer-to-peer trading volume."},{"q":"What Bitcoin-related technology does Jack Dorsey's company Block (formerly Square) develop?","options":["Bitcoin mining hardware and the TBD decentralized identity platform","Cash App exchange","A specialized bridge technology connecting Ethereum transactions to Bitcoin's blockchain network","A proprietary forked Bitcoin blockchain"],"answer":0,"explanation":"Block (formerly Square) invested in Bitcoin mining ASIC development and created TBD for decentralized identity and Bitcoin-based financial services."},{"q":"What was the significance of China's Bitcoin mining ban in 2021?","options":["It led to a change in Bitcoin's proof-of-work algorithm","It caused Bitcoin's price to crash to zero briefly","It caused a massive hash rate migration and redistribution of mining to other countries","It permanently reduced Bitcoin's total hash rate"],"answer":2,"explanation":"China's mining crackdown caused ~50% of Bitcoin's hash rate to go offline temporarily, leading to miners relocating to the US, Kazakhstan, Canada, and other countries."},{"q":"What did El Salvador build to mine Bitcoin using geothermal energy?","options":["A large dedicated solar-powered cryptocurrency mining farm operation built in the desert","A Bitcoin mining facility powered by a volcano","Hydroelectric mining dam","A wind operation"],"answer":1,"explanation":"El Salvador announced plans to use geothermal energy from volcanoes to power Bitcoin mining, setting up initial mining operations near the Tecapa volcano."},{"q":"Which payment company launched Bitcoin buying and selling for its hundreds of millions of users in 2020?","options":["Venmo Mobile Payments","Stripe Payment Processing","PayPal","Zelle Bank Transfers"],"answer":2,"explanation":"PayPal announced Bitcoin buying, selling, and holding for US users in October 2020, later expanding to Venmo and international markets."},{"q":"What is a 'Bitcoin bond' as proposed by El Salvador?","options":["A decentralized finance lending instrument","A bond instrument that automatically converts its full face value to Bitcoin at maturity","Interest-in-Bitcoin corporate bond","A government bond partially backed by Bitcoin, aimed at funding Bitcoin City"],"answer":3,"explanation":"El Salvador proposed 'Volcano Bonds' — government securities partially backed by Bitcoin — to fund Bitcoin City and Bitcoin purchases, structured with Blockstream."},{"q":"What is the significance of the 'HODL Waves' chart?","options":["New wallet creation trends over time","A chart measuring the precise frequency and intensity of price volatility during market cycles","Social media HODL tracking","It shows the age distribution of all UTXOs, revealing holding behavior patterns"],"answer":3,"explanation":"HODL Waves visualize what percentage of Bitcoin supply has remained unmoved for various time periods, revealing long-term holding conviction during market cycles."},{"q":"How many Bitcoin did Laszlo Hanyecz pay for two Papa John's pizzas on May 22, 2010?","options":["50,000 BTC","10,000 BTC","100 BTC","1,000 BTC"],"answer":1,"explanation":"Laszlo Hanyecz paid 10,000 BTC for two pizzas — the first known commercial Bitcoin transaction. May 22 is now celebrated as Bitcoin Pizza Day."},{"q":"What date is celebrated as Bitcoin Pizza Day?","options":["October 31","May 22","April 21","January 3"],"answer":1,"explanation":"May 22, 2010 — the day Laszlo Hanyecz completed the first known commercial Bitcoin transaction: 10,000 BTC for two pizzas."},{"q":"What was the very first price of Bitcoin, calculated by the cost of electricity to produce one coin?","options":["$1.00","$0.0000014","$0.01","$0.000994"],"answer":3,"explanation":"Bitcoin's first price of $0.000994 was calculated by measuring the value of electricity needed to produce one Bitcoin at the time, as documented in The Bitcoin Standard."},{"q":"El Salvador became the first nation to make Bitcoin legal tender. In what year?","options":["2021","2023","2019","2017"],"answer":0,"explanation":"In June 2021, El Salvador under President Nayib Bukele became the first nation in the world to make Bitcoin legal tender."},{"q":"What was unusual about the Bitcoin genesis block's 50 BTC reward?","options":["It was mined by accident with no difficulty target","It was double the normal block reward","It cannot be spent due to a quirk in the protocol","It was immediately sent to Hal Finney"],"answer":2,"explanation":"The protocol requires that the 50 BTC in block 0 (the genesis block) cannot be transferred — they are effectively unspendable and do not count toward the circulating supply."},{"q":"How long did it take Satoshi to mine the Bitcoin genesis block on a single CPU?","options":["2 days","6 days","24 hours","10 minutes"],"answer":1,"explanation":"While the expected time was about 7 days, Satoshi mined the Genesis Block in approximately 5.81 days — getting four leading zeros by chance at the lowest difficulty."},{"q":"What famous headline did Satoshi embed in the Bitcoin genesis block?","options":["Wall Street Journal: Federal Reserve Cuts Rates to Zero","New York Times: Economy in Worst Decline Since Depression","Financial Times: Bank of England Raises Emergency Funds","The Times 03/Jan/2009 Chancellor on brink of second bailout for banks"],"answer":3,"explanation":"Satoshi embedded this Times headline as both a timestamp and a political statement about the broken banking system that Bitcoin was designed to replace."},{"q":"Who received the very first Bitcoin transaction from Satoshi Nakamoto?","options":["Adam Back","Nick Szabo","Hal Finney","Wei Dai"],"answer":2,"explanation":"The first Bitcoin transaction was sent from Satoshi to Hal Finney on January 11, 2009, mined in block 170. All previous 169 blocks contained no transactions."},{"q":"Approximately how many lines of code did Satoshi write to create Bitcoin?","options":["1,000 lines","5,000 lines","100,000 lines","31,000–32,000 lines"],"answer":3,"explanation":"Satoshi wrote approximately 31,000–32,000 lines of code for the original Bitcoin implementation, as documented in a 2011 magazine article and later analysis."},{"q":"Today, only what percentage of Bitcoin Core's code remains unchanged from Satoshi's original?","options":["0.06%","21%","10%","50%"],"answer":0,"explanation":"Over time, almost all of Satoshi's original code has been replaced. Only 0.06% of lines in the Bitcoin Core repository remain unchanged from when Satoshi wrote them — we are all Satoshi!"},{"q":"How many confirmations must newly mined Bitcoin wait before it can be spent?","options":["101 confirmations","21 confirmations","1 confirmation","6 confirmations"],"answer":0,"explanation":"Mined (coinbase) Bitcoin cannot be spent until it has 101 confirmations — roughly 16+ hours. This prevents issues if an early block gets orphaned."},{"q":"What is the default mempool size for a Bitcoin node?","options":["10 MB","300 MB","1 GB","50 MB"],"answer":1,"explanation":"By default, a Bitcoin node allocates 300 MB for its mempool — the waiting area for unconfirmed transactions. This can be adjusted in the node's configuration file."},{"q":"How many nodes does a Bitcoin node connect to by default?","options":["1 node","50 nodes","10 other nodes","100 nodes"],"answer":2,"explanation":"By default, a Bitcoin node connects to 10 other nodes at any one time. This can be changed in the bitcoin.conf configuration file."},{"q":"When were BIP 39 seed phrases introduced?","options":["2011","2013","2017","2009"],"answer":1,"explanation":"Seed phrases (BIP 39 mnemonics) only came into existence in 2013. Before that, Bitcoin wallets used different, less user-friendly backup methods."},{"q":"What is the maximum size of a single Bitcoin transaction that nodes will relay?","options":["4 MB","10 KB","100 KB","1 MB"],"answer":2,"explanation":"100 KB is the maximum size of a single transaction that standard Bitcoin nodes will verify and relay across the network."},{"q":"What does the Bitcoin dust limit of 546 satoshis represent?","options":["The floor amount below which wallets automatically consolidate UTXOs","The minimum amount sendable at 1 sat/byte before node relay rules reject it","The smallest denomination used in Lightning Network channel balances","The minimum fee required before a transaction broadcasts to the mempool"],"answer":1,"explanation":"546 satoshis is the dust limit — the smallest amount you can send at 1 sat/byte per standard node relay rules. Many wallets use this as their default dust threshold."},{"q":"What is the maximum difficulty adjustment allowed in a single Bitcoin difficulty epoch?","options":["+50% or -25%","+100% or -50%","+1000% or -90%","+300% upward or -75% downward"],"answer":3,"explanation":"Bitcoin's difficulty adjustment is capped: it can increase by at most 300% (4x) or decrease by at most 75% (to 1/4) in a single 2016-block epoch — preventing runaway swings."},{"q":"How many rules does a Bitcoin miner check when validating a single transaction and block?","options":["100+ rules","30–40 rules each","1 main rule","3–5 rules"],"answer":1,"explanation":"When miners validate transactions, they check 30–40 individual rules for each transaction and another 30–40 rules for the block as a whole."},{"q":"Which Bitcoin address format starts with 'bc1p'?","options":["Taproot (SegWit v1)","Legacy P2PKH","P2SH wrapped SegWit","SegWit v0 (native segwit)"],"answer":0,"explanation":"Taproot addresses start with bc1p — Taproot is SegWit version 1. SegWit version 0 addresses start with bc1q (the 'q' standing for version 0, since coders start counting at 0)."},{"q":"Under what conditions will a Bitcoin node reject a block header timestamp?","options":["If it's in a different time zone than the majority of nodes","If it's more than 2 hours in the future according to the node's clock","If the timestamp doesn't match the previous block exactly","If it's older than 10 minutes"],"answer":1,"explanation":"Full nodes will not accept blocks with headers timestamped more than two hours in the future. Block timestamps must also be greater than the median of the previous 11 blocks."},{"q":"On August 15, 2010, a bug in Bitcoin created 184 billion BTC in a single transaction. What happened?","options":["The block was discovered, flagged, and the chain was rolled back in the largest reorg in Bitcoin history (53 blocks)","Satoshi remotely invalidated the extra coins using a developer admin key embedded in the original code","All extra coins were automatically routed to a known burn address encoded in Bitcoin's genesis parameters","Miners voted over several days to orphan the block, but the extra coins remained as an unclaimed supply anomaly"],"answer":0,"explanation":"The value overflow bug in block 74,638 created 184,467,440,737 BTC. Within hours, developers patched the code and the community reorganized the chain — a 53-block reorg, still the largest in Bitcoin history."},{"q":"There is a known bug in Bitcoin that will cause the chain to halt in what year if not fixed?","options":["2999","2050","2106","2140"],"answer":2,"explanation":"An overflow bug in Bitcoin's timestamp handling will cause the chain to halt in the year 2106. It's only fixable through a hard fork — something the community has plenty of time to plan."},{"q":"How many halvings are coded into Bitcoin's source code, even though new supply hits zero after just 33?","options":["33 halvings","21 halvings","64 halvings","100 halvings"],"answer":2,"explanation":"Bitcoin's source code technically encodes 64 halvings, even though the block reward effectively reaches 0 BTC after the 33rd halving. The extra 31 halvings are essentially vestigial code."},{"q":"When were ASICs first available for Bitcoin mining?","options":["2017, with the block size wars","2009, when Bitcoin launched","2015, after SegWit","2012, with Butterfly Labs' Jalapeno"],"answer":3,"explanation":"One of the first ASICs available commercially was the Butterfly Labs Jalapeno in 2012 — a small USB-sized miner that marked the end of CPU and GPU mining dominance."},{"q":"A 2007 Intel Core 2 Extreme CPU had enough power to solo mine what portion of early Bitcoin?","options":["Only the genesis block","All of the Bitcoin mined in 2009","All Bitcoin mined in the first 4 years","Less than 1% of 2009 Bitcoin"],"answer":1,"explanation":"A 2007 Intel Core 2 Extreme would have been able to solo mine all of the Bitcoin mined in the entire year of 2009 — showing how low the early difficulty was."},{"q":"Approximately how many calories of energy does it take to create 1 Bitcoin?","options":["314 billion calories","1,000 calories","100 billion calories","1 million calories"],"answer":0,"explanation":"1 Bitcoin takes approximately 314 billion calories (or 1,001 billion Joules) of energy to create — a reflection of Bitcoin's proof-of-work security model."},{"q":"Approximately what percentage of Bitcoin's total supply will have been mined by 2035?","options":["90%","75%","50%","99%"],"answer":3,"explanation":"By approximately 2035, around 99% of all Bitcoin will have been mined. The last Bitcoin won't be mined until around the year 2140 due to the halving schedule."},{"q":"How many posts did Satoshi Nakamoto make on the BitcoinTalk forums?","options":["100 posts","21 posts","10,000 posts","575 posts"],"answer":3,"explanation":"Satoshi wrote exactly 575 posts on the BitcoinTalk forums before disappearing from public view in 2010, leaving the project 'in good hands with everyone.'"},{"q":"How many known Bitcoin addresses does Satoshi Nakamoto have?","options":["100 addresses","Over 22,000 addresses","21 addresses","1 address"],"answer":1,"explanation":"Satoshi had at least 22,000 documented addresses and likely never reused a single one — demonstrating early and consistent privacy hygiene."},{"q":"What does 'Satoshi' mean in Japanese?","options":["Hidden identity, a Japanese phrase for anonymous creator","Awakening to truth, related to the Sanskrit word 'Sat'","Sound foundation, from the Japanese architectural term for base structure","Digital money, derived from the Japanese word for electronic coin"],"answer":1,"explanation":"Satoshi is a Japanese version of 'Satori' (awakening to truth), itself based on the Sanskrit word 'Sat' meaning truth or being. A fitting name for Bitcoin's creator."},{"q":"Satoshi registered which domain the day before bitcoin.org?","options":["satoshicoin.org","digitalcash.org","cryptocurrency.org","netcoin.org"],"answer":3,"explanation":"Satoshi registered netcoin.org the day before bitcoin.org — suggesting the project's name wasn't finalised until very late in development."},{"q":"What was the pre-release Bitcoin block time before Satoshi changed it to 10 minutes?","options":["30 minutes","1 minute","5 minutes","15 minutes"],"answer":3,"explanation":"The 2008 pre-release version of Bitcoin had 15-minute block times and a difficulty adjustment every 30 days. Satoshi changed both to 10-minute blocks and a 2-week adjustment before the January 2009 launch."},{"q":"What is the approximate probability of randomly guessing someone's Bitcoin private key?","options":["The same as guessing a random 6-digit PIN","About 1 in 1 million","About 1 in 1 billion","Roughly the same as winning Powerball 7 times in a row"],"answer":3,"explanation":"The chance of guessing a Bitcoin private key is astronomically small — roughly equivalent to winning the Powerball lottery 7 times consecutively."},{"q":"The chance of a wallet generating an existing seed phrase is comparable to what?","options":["Correctly predicting the outcome of 40 consecutive fair coin flips in a row","Selecting a specific atom from a grain of sand on one of Earth's beaches","Winning the national lottery jackpot twice in back-to-back weekly draws","Guessing a random 6-digit pin code on the first try without any hints"],"answer":1,"explanation":"The chance of generating an already-existing seed phrase is about the same as selecting a particular atom in a grain of sand (43 quintillion atoms per grain) from one of Earth's beaches — effectively impossible."},{"q":"To restore a Bitcoin wallet, how many letters of each seed word do you need at minimum?","options":["At least 8 letters","Only the first letter","The full word spelled correctly","The first 4 letters of each word"],"answer":3,"explanation":"You only need the first 4 letters of each BIP 39 seed word to initiate a restore — the BIP 39 wordlist was designed so no two words share the same first 4 letters."},{"q":"How much more does it cost to spend from a 2-of-3 multisig compared to a single-sig transaction?","options":["About 1.5x more","2x more","10x more","The same cost"],"answer":0,"explanation":"It costs approximately 1.5x more to spend from a 2-of-3 multisig wallet than a standard single-signature transaction, due to the extra data required for multiple signatures."},{"q":"What is the median base fee on the Lightning Network?","options":["1 satoshi","100 satoshis","0 satoshis","1,000 satoshis"],"answer":0,"explanation":"The median fee rate on the Lightning Network is a base fee of 1 satoshi plus a very small proportional fee rate — making Lightning payments nearly free for everyday amounts."},{"q":"Using SegWit, what is the theoretical maximum block size Bitcoin could scale to with just a soft fork?","options":["2 MB","4 MB","64 MB","8 MB"],"answer":2,"explanation":"With the SegWit upgrade already in place, Bitcoin's block size could technically be increased to 64 MB through just a soft fork — though the community favors keeping blocks small to preserve decentralization."},{"q":"In what year did Bitcoin have no price at all?","options":["2008, before launch","2010, after Pizza Day","Bitcoin always had a price","For the first ~10 months after launch (2009)"],"answer":3,"explanation":"Bitcoin had no price for approximately the first 10 months after its January 2009 launch. The first recorded price didn't appear until late 2009, when Satoshi himself made an early exchange."},{"q":"What was notable about the Overstock.com Bitcoin milestone in 2014?","options":["It was one of the first major national retailers to accept Bitcoin as payment","It was the first company to put Bitcoin on its balance sheet","It launched the first Bitcoin ETF","It was the first company to pay employee salaries in Bitcoin"],"answer":0,"explanation":"Overstock.com became one of the first major national retailers to begin accepting Bitcoin as payment in 2014 — a milestone for mainstream Bitcoin commerce."},{"q":"What is the Bitcoin whitepaper encoded in on the blockchain?","options":["Block 230,009","Block 1 (genesis)","Block 21,000","Block 666,666"],"answer":0,"explanation":"Bitcoin's original whitepaper is encoded in block 230,009 — a piece of Bitcoin history permanently inscribed on the timechain itself."},{"q":"The Bitcoin difficulty adjustment happens every how many blocks?","options":["2,016 blocks","1,000 blocks","210,000 blocks","144 blocks"],"answer":0,"explanation":"Bitcoin's difficulty adjusts every 2,016 blocks — approximately every 2 weeks — to ensure blocks continue to be found roughly every 10 minutes regardless of total hash rate."},{"q":"In Bitcoin lore, 2,016 (the difficulty epoch length) is the semordnilap of which famous Executive Order?","options":["Executive Order 2016, creating the Federal Open Market Committee","Executive Order 9066, which authorized Japanese internment","Executive Order 6102, which forced Americans to sell their gold to the Federal Reserve","Executive Order 6,210, the first banking holiday decree"],"answer":2,"explanation":"Bitcoin difficulty adjusts every 2,016 blocks — the semordnilap (reverse) of 6,102, the Executive Order that forced Americans to hand over gold under threat of imprisonment."},{"q":"What famous event happened to a UK man's hard drive containing 7,500 Bitcoin?","options":["It was destroyed in a house fire along with printed seed backups — the Bitcoin is permanently unrecoverable","It was stolen by hackers who remotely accessed a backup server and wiped the decryption keys from all devices","It was seized by UK tax authorities during a cryptocurrency investigation and auctioned at a government surplus sale","He accidentally threw it away and it is buried in a UK landfill — he has been fighting authorities to excavate it ever since"],"answer":3,"explanation":"James Howells of Wales accidentally discarded a hard drive containing 7,500 BTC, which ended up in a local landfill. His ongoing quest to excavate and recover it has become one of Bitcoin's most famous lost-coin stories."},{"q":"Bitcoin's original source code contained the beginning of what unexpected feature Satoshi never finished?","options":["A Bitcoin-based email client","A price ticker with live exchange rates","An in-wallet chat system","A virtual poker game"],"answer":3,"explanation":"The original Bitcoin code includes the beginnings of a virtual poker game that Satoshi is believed to have started but never finished — a fascinating Easter egg in early Bitcoin history."},{"q":"In block 124,724, what happened to permanently remove 1 satoshi from Bitcoin's supply?","options":["A competing miner submitted an alternative block at the same height that orphaned 1 satoshi through a chain split","Solo miner midnightmagic produced 49.99999999 BTC instead of 50, permanently removing 1 satoshi from Bitcoin's supply","A fee rounding error in the transaction validation engine caused exactly 1 satoshi to be double-counted and voided","Satoshi intentionally burned exactly 1 satoshi from that block as a cryptographic proof-of-burn timestamp signature"],"answer":1,"explanation":"User midnightmagic solo mined block 124,724 and produced 49.99999999 BTC instead of 50 — because the block subsidy is calculated by block height, not remaining supply. That 1 sat is gone forever, slightly reducing the total supply from 21 million."},{"q":"What happened to Bitcoin's network on the two occasions it went down in its history?","options":["Once for 24 hours due to a DDoS attack and once for 48 hours due to a mining bug","Once for 8h 27m due to the value overflow bug (2010) and once for 6h 20m due to a database fork (2013)","Once for 1 hour during the first halving and once for 2 hours during SegWit activation","It has never gone down — Bitcoin has 100% uptime"],"answer":1,"explanation":"Bitcoin has experienced two notable outages: the 2010 value overflow incident (8h 27m) and a 2013 database compatibility issue (6h 20m). Both were resolved through community consensus to roll back blocks."},{"q":"Hal Finney created a video game in 1982 — what was it called?","options":["Bitcoin Quest","Hashrate Hero","The Adventures of Tron","Cypherpunk Chronicles"],"answer":2,"explanation":"Before becoming one of Bitcoin's earliest contributors, Hal Finney created The Adventures of Tron in 1982 — a game for the Atari 2600. Hal also wrote about NFT-like concepts in 1993, decades before they became mainstream."},{"q":"The 1991 video game Space Quest IV featured a currency that eerily resembled what?","options":["The Ethereum diamond logo","Bitcoin's ₿ symbol","The US dollar sign","A gold coin icon"],"answer":1,"explanation":"Space Quest IV: Roger Wilco and the Time Rippers (1991) featured a currency called the 'Buckazoid' — with a symbol strikingly similar to Bitcoin's ₿ logo, more than a decade before Bitcoin existed."},{"q":"According to Nikola Tesla, numbers 3, 6, and 9 are the keys to the universe. How do Bitcoiners map these to Bitcoin?","options":["Block reward 3.125 BTC, difficulty target with 6 leading zeros minimum, 9 years for 90% supply mined","21M → 2×1=2, then 2+halving_count=3; 6 confirmations for finality; block height 9 in genesis era","3 Bitcoin price cycles to date, 6 confirmed Satoshi email addresses found, 9 known core developers","21M coins → 2+1+0...=3, 33 halvings → 3+3=6, difficulty every 2,016 blocks → 2+0+1+6=9"],"answer":3,"explanation":"The Bitcoin–Tesla numerology: 21,000,000 coins → 2+1+0...=3; 33 halvings → 3+3=6; difficulty adjustment every 2,016 blocks → 2+0+1+6=9. All three of Tesla's special numbers encoded in Bitcoin's design."},{"q":"What anomaly did an object called GPM J1839-10 contribute to Bitcoin lore?","options":["It was named after Satoshi Nakamoto by an astronomer","It blinks every 21 minutes and has done so since 1988 — dubbed the 'Star of Satoshi-hem'","It emits radio waves in patterns matching Bitcoin's block time","It was discovered on October 31, the day the whitepaper was published"],"answer":1,"explanation":"GPM J1839-10 is a star-like object that has been blinking every 21 minutes since 1988 — long before Bitcoin. Some Bitcoiners call it the 'Star of Satoshi-hem,' noting the curious connection to the 21 million supply cap."},{"q":"How long can Bitcoin transactions be timelocked into the future using Bitcoin's technical maximum?","options":["Approximately 9,000 years","Until block 21,000,000","Until the year 2140","100 years maximum"],"answer":0,"explanation":"Using Bitcoin's CLTV (CheckLockTimeVerify) opcode with the maximum timestamp value, funds can technically be timelocked for approximately 9,000 years into the future."},{"q":"In numerology, what number is the sum of Bitcoin's 2+1+6 (difficulty epoch length)?","options":["9","6","21","3"],"answer":0,"explanation":"The difficulty adjustment epoch of 2,016 blocks: 2+0+1+6=9. Nikola Tesla claimed 3, 6, and 9 are the keys to the universe — all three appear directly in Bitcoin's core parameters."},{"q":"How many approximately 300–400 byte transactions fit into a 1 MB Bitcoin block?","options":["3,000–4,000 transactions","100 transactions","10,000 transactions","1,000 transactions"],"answer":0,"explanation":"A Bitcoin transaction is typically 300–400 bytes. With 1,000,000 bytes in a megabyte, a 1 MB base block can fit roughly 3,000–4,000 standard transactions."},{"q":"What is the average number of transactions per second Bitcoin has achieved across its lifetime?","options":["Over 1,000 TPS","About 100 TPS with SegWit","Fewer than 10 TPS on the base layer","Exactly 7 TPS (by design)"],"answer":2,"explanation":"Bitcoin's base layer handles roughly 3–7 transactions per second on average. The Lightning Network, by contrast, can process millions of transactions per second off-chain."},{"q":"Where is an obituary for cypherpunk Len Sassaman permanently stored?","options":["Embedded in every Bitcoin node as a transaction on the timechain","In the Bitcoin whitepaper's references section","In block 0 alongside the genesis block headline","In the Bitcoin Core repository README file"],"answer":0,"explanation":"An obituary for Len Sassaman — a cypherpunk who had direct impact on Bitcoin's creation — is embedded on the Bitcoin timechain and thus stored in every full node. Many believe he may have been Satoshi Nakamoto."},{"q":"How many halvings align between Bitcoin's halving cycle (every 210,000 blocks) and its difficulty epoch (every 2,016 blocks)?","options":["Every 1,260,000th block (every ~24 years)","They never align precisely","Every block — they always align","Every 21,000th block"],"answer":0,"explanation":"Bitcoin halvings (every 210,000 blocks) and difficulty epochs (every 2,016 blocks) align every 1,260,000th block — approximately every 24 years. The math: LCM(210,000, 2,016) = 1,260,000."},{"q":"What was the Bitaxe solo miner's estimated probability of finding a block in July 2024?","options":["1 in 1,000 years","1 in 21 million","1 in 3,500 years (which it actually did)","1 in 10 days"],"answer":2,"explanation":"In July 2024, a Bitaxe home miner with just 3 TH/s successfully found a Bitcoin block — an event with roughly a 1-in-3,500-year statistical probability. One of Bitcoin's most celebrated solo mining moments."}];
